'use strict';

const { ask4 } = require('../../../lib/util/question');

class NonTTYError extends Error {
  constructor(message = 'non-interactive stdin') {
    super(message);
    this.name = 'NonTTYError';
  }
}

// Exported for unit testing; not part of the public API.
function _parseAnswer(raw, defaultYes) {
  const s = (raw || '').trim().toLowerCase();
  if (s === '') return defaultYes;
  if (s === 'y' || s === 'yes') return true;
  if (s === 'n' || s === 'no') return false;
  return defaultYes;
}

async function askYesNo(question, { defaultYes = true } = {}) {
  if (!process.stdin.isTTY) throw new NonTTYError();
  const suffix = defaultYes ? ' (Y/n) ' : ' (y/N) ';
  const raw = await ask4([question + suffix]);
  return _parseAnswer(raw, defaultYes);
}

module.exports = { askYesNo, NonTTYError, _parseAnswer };
